-- +goose Up
-- The catalogue of places, as it was when it left the intranet it was born in: the schema `catalogue` with
-- its seeded reference data (the types, the subtypes and the geologies of places, and the zones of the
-- world: the states, and for Spain its communities, provinces and municipalities). It is the sum of the
-- migrations 00061 to 00083 of that repository, which are not kept. The tables of the intranet's own
-- (people, activities…) are not here, and neither is the club's account or its issuer: a client is
-- registered with `cmd/issuer`.

